window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-86732b977d112c5e"]={"versions": [{"id": "FIG-86732b977d112c5e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code>.</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}, {"id": "FIG-44845df43dc3228e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code>.</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}, {"id": "FIG-33c05ceaa38358f7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code>.</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger [0..1]</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger [0..1]</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String [0..1]</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger [0..1]</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}, {"id": "FIG-10698cf77769baa0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code>: Versionsbezeichner des Schnittstellenvertrags zur Sicherstellung der Kompatibilität.</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code>.</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger [0..1]</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger [0..1]</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String [0..1]</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger [0..1]</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}, {"id": "FIG-7abb8127334b3826", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code>: Versionsbezeichner des Schnittstellenvertrags zur Sicherstellung der Kompatibilität.</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code>.</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger [0..1]</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger [0..1]</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String [0..1]</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger [0..1]</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}, {"id": "FIG-b23c1b3b980b08b8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Adaptive Platform, Release R20-11).</li>\n<li><strong>Architektonische Einordnung:</strong> Spezifikation von Datenintegritäts- und Ausfallsicherheitsmechanismen (Redundanzstrategien) für persistente Datenhaltung (<code>ara::per</code>) auf Ebene der Schnittstellenbeschreibung (<code>PersistencyInterface</code>, abgeleitet von <code>PortInterface</code>).</li>\n<li><strong>Funktionaler Zweck (RS_MANI_00027, TPS_MANI_01320):</strong> Ermöglicht die deklarative Konfiguration von Integritätsschutz (Erkennung von Bitfehlern) und Fehlertoleranz (Wiederherstellung von Nutzdaten) für Key-Value-Datenbanken oder File-Proxy-Strukturen, ohne anwendungsspezifischen Code zu belasten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> (Spezialisierung von <code>PortInterface</code>):</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code>: Versionsbezeichner des Schnittstellenvertrags zur Sicherstellung der Kompatibilität.</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code>: Mindestgarantie für persistenten Speicherplatz.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code>: Globale Klassifizierung der Redundanzanforderung.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code>: Aktualisierungssemantik auf Collection-Ebene.</li>\n<li>Assoziationsende (Komposition): Aggregiert <code>0..*</code> Instanzen von <code>PersistencyRedundancyHandling</code> über die Rolle <code>redundancyHandling</code> mit Stereotyp <code>«atpSplitable»</code> (ermöglicht die Verteilung über mehrere Manifest-/ARXML-Dateien).</li>\n<li><strong><code>PersistencyRedundancyHandling</code></strong> (<em>abstrakt</em>):</li>\n<li>Basisklasse für konkrete Redundanz- und Integritätsverfahren.</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code>: Definiert den Wirkungsbereich des Verfahrens (z. B. elementbezogen vs. sammlungs-/gesamtdateibezogen).</li>\n<li><strong><code>PersistencyRedundancyMOutOfN</code></strong> (konkret, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Realisiert Replikation und Mehrheitsentscheid (Majority Voting / N-Modular Redundancy).</li>\n<li><code>m: PositiveInteger [0..1]</code>: Mindestanzahl übereinstimmender Replikate für ein gültiges Leseergebnis ($M$).</li>\n<li><code>n: PositiveInteger [0..1]</code>: Gesamtzahl der gespeicherten physischen Replikate ($N$, wobei $M \\le N$).</li>\n<li><strong><code>PersistencyRedundancyChecksum</code></strong> (<em>abstrakt</em>, erbt von <code>PersistencyRedundancyHandling</code>):</li>\n<li>Generische Prüfsummen- und Hash-Verfahren zur Fehlererkennung.</li>\n<li><code>algorithmFamily: String [0..1]</code>: Spezifikation der Algorithmenfamilie (z. B. <code>\"CRC\"</code>, <code>\"SHA\"</code>).</li>\n<li><code>length: PositiveInteger [0..1]</code>: Bit-/Byte-Länge des Prüfwerts.</li>\n<li><strong><code>PersistencyRedundancyCrc</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Zyklische Redundanzprüfung (Hardware- oder Tabellen-CRC).</li>\n<li><strong><code>PersistencyRedundancyHash</code></strong> (konkret, erbt von <code>PersistencyRedundancyChecksum</code>):</li>\n<li>Kryptografische Hash-Funktionen.</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code>: Optionale Länge des Initialisierungsvektors (IV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell enthält das Diagramm keine dynamischen Sequenzen. Zur Laufzeit induziert die Konfiguration folgende Abläufe im Persistency-Stack (<code>ara::per</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Schreibpfad (Synchron / Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::SetValue()</code> bzw. <code>FileStorage::WriteFile()</code>.</li>\n<li>Der Persistency-Stack berechnet gemäß <code>PersistencyRedundancyHandling</code> die Prüfsummen (<code>CRC</code>/<code>Hash</code>) und/oder dupliziert die Nutzdaten $N$-fach (<code>MOutOfN</code>).</li>\n<li>Atomare Speicherung von Payload und Metadaten/Redundanzdaten auf dem persistenten Speichermedium (z. B. eMMC, NVRAM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lesepfad & Integritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>ara::per::KeyValueStorage::GetValue()</code> bzw. File-Read.</li>\n<li><strong>Checksum/CRC/Hash:</strong> Validierung der Prüfsumme. Bei Mismatch: Rückgabe von <code>PerErrc::kIntegrityCorrupted</code>.</li>\n<li><strong>MOutOfN:</strong> Auslesen aller $N$ Replikate und Vergleich. Bei mindestens $M$ identischen Blöcken gilt der Block als valide (Heilung defekter Replikate durch den Stack möglich); bei $< M$ konsistenten Replikaten schlägt die Operation mit einem Fehler fehl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Entwickler müssen Redundanzverfahren im ARXML-Manifest (<code>Execution Manifest</code> / <code>Service Instance To Port Prototype Mapping</code>) auf die geforderte ASIL-Einstufung abstimmen.</li>\n<li><code>PersistencyRedundancyMOutOfN</code> erhöht den Speicherplatzbedarf um den Faktor $N$ sowie die Schreiblatenz signifikant; $M$ und $N$ müssen sorgfältig gegen Endurance-Limits des Flash-Speichers abgewogen werden.</li>\n<li><strong>Transparenz für Applikationscode:</strong></li>\n<li>Die <code>ara::per</code>-API selbst bleibt für die Applikation identisch; Redundanzprüfung und Fehlerkorrektur erfolgen transparent innerhalb der Plattformimplementierung.</li>\n<li>Fehlerfälle (z. B. unkorrigierbare Datenverfälschung) werden über AUTOSAR-Fehlercodes (<code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code>) an die Applikation gemeldet und erfordern deterministische Fallback-/Safe-State-Strategien.</li>\n<li><strong>Plattform- & Treiber-Einschränkungen:</strong></li>\n<li>Bei Verwendung von <code>PersistencyRedundancyHash</code> mit IV oder hardwarebeschleunigtem CRC müssen die konfigurierten Algorithmenfamilien (<code>algorithmFamily</code>) vom zugrundeliegenden OS, Crypto-Stack oder Hardware-Beschleuniger des SoCs unterstützt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-86732b977d112c5e", "to": "FIG-44845df43dc3228e", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>PersistencyRedundancyChecksum: Kastenhöhe verringert (vertikaler Leerraum unterhalb der Attribute entfernt).</li>\n<li>PersistencyRedundancyHash: Kastenhöhe verringert (vertikaler Leerraum unterhalb des Attributs entfernt).</li>\n<li>PersistencyRedundancyCrc: Kastenhöhe verringert (vertikaler Leerraum unterhalb des Klassennamens entfernt).</li>\n</ul>"}, {"from": "FIG-44845df43dc3228e", "to": "FIG-33c05ceaa38358f7", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PersistencyRedundancyChecksum: Multiplizität der Attribute algorithmFamily und length von [1] auf [0..1] geändert.</li>\n<li>PersistencyRedundancyMOutOfN: Multiplizität der Attribute m und n von [1] auf [0..1] geändert.</li>\n</ul>"}, {"from": "FIG-33c05ceaa38358f7", "to": "FIG-10698cf77769baa0", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PersistencyInterface: Attribut contractVersion: StrongRevisionLabelString [0..1] ergänzt.</li>\n</ul>"}, {"from": "FIG-10698cf77769baa0", "to": "FIG-7abb8127334b3826", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7abb8127334b3826", "to": "FIG-b23c1b3b980b08b8", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PersistencyInterface: Aggregation redundancyHandling mit dem Stereotyp «atpSplitable» versehen.</li>\n<li>PersistencyRedundancyHandling: Generalisierungsbeziehung von geteilter Verzweigung auf separate Generalisierungspfeile für PersistencyRedundancyChecksum und PersistencyRedundancyMOutOfN umgestellt.</li>\n</ul>"}]};
